\label{2.1}
Let $R$ be a Noetherian ring, $I$ be an ideal of $R$ and $T$ be an $R$-module. Then  the following statements are equivalent:
\begin{itemize}
 \item[(i)] The $R$-module $H^i_I(T)$ is Artinian, for $i\geq 0$.
 \item[(ii)] The $R$-module $\operatorname{Ext}^i_R(R/I,T)$ is Artinian, for $i\geq 0$.
\item[(iii)] The $R$-module $\operatorname{Ext}^i_R(R/I,T)$ is Artinian, for $0 \leq i \leq \operatorname{cd}(I,R)$.
\end{itemize}

\label{2.2}
 Let $(R,\operatorname{\frak m})$ be a Noetherian local ring, $I$ be an ideal of $R$ and $M$ be an $R$-module. Then the following conditions
are equivalent:
\begin{itemize}
 \item[(i)] The $R$-modules $\operatorname{Tor}^R_{i}(R/I,M)$ are finitely generated for all $i\geq 0$.
 \item[(ii)] The $R$-modules $\operatorname{Tor}^R_{i}(R/I,M)$ are finitely generated for all $0\leq i\leq \operatorname{cd}(I,R)$.
\end{itemize}

\label{3.2}
  Let $R$ be a Noetherian ring, $I$ be an
ideal of $R$ and $M$ be an $R$-module. Then the following conditions
are equivalent:
\begin{itemize}
 \item[(i)]  $\operatorname{Tor}^R_{n}(R/I,M)=0$, for all integers $n\geq 0$.
 \item[(ii)] $\operatorname{Ext}^n_{R}(R/I,M)=0$, for all integers $n\geq 0$.
 \end{itemize}

\label{3.4}
Let $R$ be a Noetherian ring and let $I\subseteq J$ be two ideals of $R$.
Let $M$ be an $R$-module and $t\geq 2 $ be an integer such that $\operatorname{Tor}^R_j(R/J,H^i_I(M))=0$ for all $i>t$ and all $j\geq0$. Then we have $\operatorname{Tor}^R_j(R/J,H^t_I(M))=0$ for $j=0,1$.

\label{3.6}
 Let $R$ be a Noetherian ring, $I$ be an
ideal of $R$ and $M$ be an $R$-module. Then the following conditions
are equivalent:
\begin{itemize}
 \item[(i)] $\operatorname{Tor}^R_{i}(R/I,M)=0$, for all $i\geq 0$.
 \item[(ii)] $\operatorname{Tor}^R_{i}(R/I,M)=0$, for all $0\leq i\leq \operatorname{cd}(I,R)$.
\end{itemize}

\label{3.7}
  Let $R$ be a Noetherian ring and $I$ be an
ideal of $R$. Then the following conditions
are equivalent:
\begin{itemize}
 \item[(i)]  ${\rm cd}(I,R)\leq 1$.
 \item[(ii)] The ideal transform functor $D_I(-)$ is exact.
 \item[(iii)] For every $R$-module $M$, if $\operatorname{Tor}^R_{i}(R/I,M)=0$ for $i=0,1$, then $\operatorname{Tor}^R_{i}(R/I,M)=0$, for all integers $i\geq 0$.
 \item[(iv)] For every $R$-module $M$, if $\operatorname{Ext}^i_{R}(R/I,M)=0$ for $i=0,1$, then $\operatorname{Ext}^i_{R}(R/I,M)=0$, for all integers $i\geq 0$.
\end{itemize}

\label{3.8}
 Let $R$ be a Noetherian ring and let $I=Ra_1+Ra_2$ be an
ideal of $R$. Then the following conditions
are equivalent:
\begin{itemize}
 \item[(i)]  ${\rm cd}(I,R)=2$.
 \item[(ii)] There exists an $R$-module $M$, such that $\operatorname{Tor}^R_{i}(R/I,M)=0$ for $i=0,1$ and $\operatorname{Tor}^R_{2}(R/I,M)\neq0$.
 \item[(iii)] There exists an $R$-module $M$, such that $\operatorname{Ext}^i_{R}(R/I,M)=0$ for $i=0,1$ and $\operatorname{Ext}^2_{R}(R/I,M)\neq0$.
\end{itemize}

\label{4.1}
  Let $R$ be a Noetherian ring and let $I\subseteq J$ be two ideals of $R$ such that $\operatorname{cd}(J,R)=1$. Then the following statements hold:
\begin{itemize}
 \item[(i)]  For every $R$-module $M$ we have $\operatorname{Ext}^j_R(R/J,H^i_I(M))=0$, for all integers $i\geq 2$ and $j\geq 0$.
 \item[(ii)] For every $R$-module $M$ and every finitely generated $R$-module $N$ with $\operatorname{Supp} N \subseteq V(J)$ we have $\operatorname{Ext}^j_R(N,H^i_I(M))=0$, for all integers $i\geq 2$ and $j\geq 0$.
 \item[(iii)] For every $R$-module $M$ and each prime ideal $\operatorname{\frak p}\in V(J)$ we have $\mu^j(\operatorname{\frak p},H^i_I(M))=0$, for all integers $i\geq 2$ and $j\geq 0$. $($Here $\mu^j(\operatorname{\frak p},H^i_I(M))$ denotes the j-th Bass number of the $R$-module $H^i_I(M)$ with respect to $\operatorname{\frak p}$$)$.
 \item[(iv)]  For every $R$-module $M$ and each prime ideal $\operatorname{\frak p}\in V(J)$ we have $\beta_j(\operatorname{\frak p},H^i_I(M))=0$, for all integers $i\geq 2$ and $j\geq 0$. $($Here $\beta_j(\operatorname{\frak p},H^i_I(M))$ denotes the j-th Betti number of the $R$-module $H^i_I(M)$ with respect to $\operatorname{\frak p}$$)$.
\end{itemize}

\label{4.2}
 Let $R$ be a Noetherian domain and let $I$ and $J$ be two non-zero proper
 ideals of $R$ such that $\operatorname{cd}(J,R)=1$ and $J\not\subseteq \operatorname{Rad} (I)$. Then we have $$\operatorname{cd}(I\cap J,R)=\max\{i\in \Bbb{Z}\,\,:\,\,\operatorname{Supp} H^i_I(R)\not\subseteq V(J)\}.$$

\label{4.4}
